// HET HERSTEL VAN EEN GROTE OPEN-STAND, GEFASEERD (opruimpunt 67, 14 sep 2026).
//
// DE MELDING: "Na reload zegt hij nu ook 'This page is slowing down Firefox'."
// GEMETEN (fold-vouw-perf.md, 14 sep, jenv-corpus, 141 formulieren): het
// herstel liep in 12.018 ms, en dáárvan zat 11.467 ms in ÉÉN taak. Zo'n taak is
// precies wat een browser "this page is slowing down" noemt: de hoofddraad
// antwoordt elf seconden lang op geen enkele klik, toets of scroll.
//
// WAAROM HET ÉÉN TAAK WAS. De bewaarde open-stand is hier geen nabewerking maar
// de STARTSTAND van elk blok (zie de kop van `stores/openstand.ts`): een
// `KnoopVouwOpen` die open geboren wordt, rendert meteen zijn formulier, dat
// rendert zijn eigen vouwkoppen, en die worden op hun beurt open geboren. Het
// hele herstel hangt zo aan één synchrone render — honderdenveertig formulieren
// diep, zonder één moment waarop de browser ertussen kan.
//
// WAT DEZE WACHTRIJ ERVAN MAAKT. Een vouw die uit de BEWAARDE stand open komt,
// meldt zich hier en bouwt zijn body pas als hij aan de beurt is. Per slice
// wordt er hooguit `BUDGET_MS` aan werk gedaan, en daarna geeft de rij de
// hoofddraad terug. De boom groeit daarmee laag voor laag in plaats van in één
// stuk: elke gebouwde body meldt zijn eigen geneste vouwen weer aan.
//
// DRIE EIGENSCHAPPEN DIE NIET MOGEN VERSCHUIVEN, en waarom ze hier staan:
//
//  1. WAT IN BEELD STAAT GAAT VOOR. Zonder voorrang bouwt de rij in
//     documentvolgorde, en dan kijkt de lezer die halverwege de pagina staat
//     seconden naar lege vouwen terwijl er onzichtbaar werk gedaan wordt. De
//     keuze gebeurt PER SLICE en niet per taak: `getBoundingClientRect` dwingt
//     een layout af, en één zo'n meting per taak zou de winst opeten. De scan
//     is bovendien begrensd (`SCAN`) — hij mag zelf nooit het budget worden.
//  2. EEN KLIK WACHT NOOIT. De rij geldt alleen voor de HERSTELstand; wie zelf
//     een vouw openklapt krijgt hem meteen (zie `KnoopVouwOpen`). Een lezer die
//     op een wachtende vouw klikt zou anders naar een lege body kijken.
//  3. NIETS KLAPT OM. De `<details>` staat vanaf het eerste beeld open; alleen
//     zijn INHOUD komt later. De open-stand zelf wordt door deze rij niet
//     aangeraakt en er wordt niets weggeschreven — de administratie blijft wat
//     de lezer ervan maakte.
//
// DE SLICE-TERUGVAL. `requestIdleCallback` is de juiste primitief (hij wacht op
// een moment waarop de browser niets beters te doen heeft) maar hij bestaat niet
// overal — Safari heeft hem nog altijd niet. De terugval is `setTimeout(…, 0)`,
// hetzelfde idioom als `hydrateInto` in `model/graaf-overdracht.js` gebruikt om
// een grote store in stukjes te vullen. Zelfde vorm, zelfde reden.

/** Eén wachtende vouw: waar hij staat, en wat er moet gebeuren als hij aan de
 *  beurt is. `el` is een functie omdat de ref pas ná de component-opbouw gevuld
 *  is. */
export interface HerstelTaak {
  el: () => Element | null | undefined;
  bouw: () => void;
}

// HET TIJDBUDGET PER SLICE. 12 ms is ruim onder de 50 ms die de browser zelf als
// `longtask` telt, en laat dus ruimte voor de ene body die zelf groter is dan
// het budget: die wordt niet afgebroken (een half formulier bestaat niet), hij
// loopt zijn slice uit. De grens bewaakt hoeveel er NÁ hem nog in dezelfde taak
// bij komt, en dat is waar de opstapeling zat.
const BUDGET_MS = 12;
// Hoeveel wachtenden er per slice hoogstens op zichtbaarheid bekeken worden.
const SCAN = 40;
// De rand om het venster die als "in beeld" telt: wat net onder de vouw hangt is
// één scrollduw ver, en die duw moet niet op een lege body landen.
const RAND_PX = 600;

const wacht: HerstelTaak[] = [];
let gepland = false;

const nu = (): number => (typeof performance === 'undefined' ? Date.now() : performance.now());

function planSlice(): void {
  if (gepland) return;
  gepland = true;
  const w = globalThis as unknown as {
    requestIdleCallback?: (cb: () => void, o?: { timeout: number }) => void;
  };
  // `timeout` erbij: een tabblad dat op de achtergrond staat krijgt anders nooit
  // een idle-moment, en dan zou het herstel er bij terugkomst nog niet zijn.
  if (typeof w.requestIdleCallback === 'function') w.requestIdleCallback(draai, { timeout: 250 });
  else setTimeout(draai, 0);
}

/** De eerste wachtende die IN BEELD staat, of 0 als er geen zichtbare tussen de
 *  eerste `SCAN` zit. Eén rect-meting per bekeken taak, hoogstens `SCAN` per
 *  slice. */
function kiesZichtbare(): number {
  const h = typeof window === 'undefined' ? 0 : window.innerHeight;
  if (!h) return 0;
  const grens = Math.min(wacht.length, SCAN);
  for (let i = 0; i < grens; i += 1) {
    const el = wacht[i].el();
    if (!el || !el.isConnected) continue;
    const r = el.getBoundingClientRect();
    if (r.bottom >= -RAND_PX && r.top <= h + RAND_PX) return i;
  }
  return 0;
}

function draai(): void {
  gepland = false;
  const einde = nu() + BUDGET_MS;
  while (wacht.length) {
    const t = wacht.splice(kiesZichtbare(), 1)[0];
    const el = t.el();
    // Een vouw die intussen is opgeruimd (ander corpus, kaart dichtgeklapt)
    // heeft niets meer te bouwen. Stil overslaan: het is geen fout.
    if (el && el.isConnected) t.bouw();
    // NA het bouwen kijken en niet ervoor: anders doet een slice bij een vol
    // budget nul werk en draait de rij zichzelf rond zonder op te schieten.
    if (nu() >= einde) break;
  }
  if (wacht.length) planSlice();
}

/** Deze vouw komt uit de BEWAARDE stand open; bouw hem zodra er ruimte is. */
export function herstelLater(taak: HerstelTaak): void {
  wacht.push(taak);
  planSlice();
}

/** Hoeveel vouwen wachten er nog? Voor toetsen en voor de meting. */
export const herstelWachtrij = (): number => wacht.length;

/** Alles wat nog wacht NU bouwen. Voor toetsen (een unittest heeft geen idle
 *  moment) en voor elke aanroeper die de volledige stand ineens nodig heeft. */
export function herstelNu(): void {
  while (wacht.length) {
    const t = wacht.shift()!;
    const el = t.el();
    if (el && el.isConnected) t.bouw();
  }
}

/** De rij leegmaken zonder te bouwen — bij een corpuswissel is wat erin staat
 *  van het vorige document. */
export function vergeetHerstelWachtrij(): void {
  wacht.length = 0;
}
