// HET WEERGAVEMODEL VAN EEN DOMEINFORMULIER — de brug tussen `model/forms.js`
// en de weergave.
//
// Gedragsbron: `loadedFormShapes`, `shapeFormFor` en `artifactForm` in de
// bevroren `viewer-bevroren/assets/doc.js` (r.8854-9140). De MODELKANT (welke shape,
// welke rijen, welke waarden) staat ongewijzigd in `src/model/forms.js` en is
// daar getest; dit bestand doet alleen wat de viewer erboven deed: de shapes
// van dit moment bij elkaar zoeken en er één formulier van maken.
//
// WAAROM DIT GEEN COMPONENT IS. Het formulier hangt aan de GRAAF, niet aan een
// prop: dezelfde knoop levert na een taalwissel andere labels en na een mutatie
// andere waarden. `graafVersie()` wordt daarom hier meegelezen — één plek, zodat
// elke aanroeper vanzelf reactief is (dezelfde afspraak als `ProvRef` in
// body-rijen.tsx en de ledenboom).
//
// TWEE INGANGEN, en het verschil is precies dat van de bevroren viewer:
//   `vormVoorKnoop(iri)`  — welke shape dekt deze knoop? Geen enkele: null.
//   `artefactVorm(iri)`   — de aanroeper WEET dat dit een artefact is en geeft
//                           de meegeleverde shape als terugval mee, ook als de
//                           knoop geen passend rdf:type draagt.
import {
  builtinShapes, countCovered, coveredClasses, dropBacklinks, formModel, isCovered, keyInfoFor,
  readShapes, shapeForNode, shapeForNodeIndexed, shapeIndex, typeLabelFor,
} from '../../model/forms.js';
import { ARTIFACT_FORM_SHAPE_TTL } from '../../model/artifact-form-shape.js';
import { getLang } from '../../model/i18n.js';
import { gedektTelling, graaf, graafVersie } from '../../stores/corpus.js';
import type { Graaf } from '../../model-grens.js';

/** Eén waarde van een rij. `kind` zegt hoe de weergave haar tekent (forms.js):
 *  `text` letterlijk, `link` de IRI zelf als link, `label` het label van de
 *  doelknoop — met `external` voor een knoop die buiten het corpus ligt. */
export interface FormWaarde {
  kind: 'text' | 'link' | 'label';
  text: string;
  iri: string | null;
  external?: boolean;
}

export interface FormRij {
  kind: 'row';
  label: string;
  description: string | null;
  /** Het predicaat waar deze rij aan hangt, en de RICHTING waarin het gelezen
   *  is. Beide zijn nodig zodra de rij bewerkbaar wordt (zie forms.js). */
  path: string | null;
  inverse: boolean;
  pattern: string | null;
  viewer: string | null;
  values: FormWaarde[];
  order: number | null;
}

export interface FormGroep {
  kind: 'group';
  label: string;
  rows: FormRij[];
  order: number | null;
}

export type FormBlok = FormGroep | FormRij;

export interface FormVorm {
  shape: string;
  title: string;
  keyInfo: FormWaarde[];
  description: string | null;
  blocks: FormBlok[];
}

interface Shape { iri: string; targetClass: string; store: unknown; properties: unknown[] }

const leesShapes = readShapes as unknown as (store: Graaf) => Shape[];
const ingebouwd = builtinShapes as unknown as (ttl: string[]) => Shape[];
const shapeVoorKnoop = shapeForNode as unknown as (
  store: Graaf, iri: string, shapes: Shape[], fallbacks?: Shape[]) => Shape | null;
const bouwVorm = formModel as unknown as (store: Graaf, iri: string, shape: Shape) => FormVorm;
const gedekteKlassen = coveredClasses as unknown as (
  store: Graaf, shapes: Shape[]) => Set<string>;
const knoopGedekt = isCovered as unknown as (
  store: Graaf, iri: string, klassen: Set<string>) => boolean;
const telGedekt = countCovered as unknown as (store: Graaf, klassen: Set<string>) => number;
type ShapeIndex = Map<string, { shape: Shape }>;
const bouwIndex = shapeIndex as unknown as (
  store: Graaf, shapes: Shape[], fallbacks?: Shape[]) => ShapeIndex;
const shapeUitIndex = shapeForNodeIndexed as unknown as (
  store: Graaf, iri: string, index: ShapeIndex) => Shape | null;
const kerngegeven = keyInfoFor as unknown as (
  store: Graaf, iri: string, shape: Shape | null) => FormWaarde[];
const typeLabel = typeLabelFor as unknown as (
  store: Graaf, shape: Shape | null) => TypeLabel | null;

/** De type-pil van een vouwkop: `text` staat erin, `vol` in het
 *  title-attribuut, `afgekort` zegt of die twee verschillen. */
export interface TypeLabel { text: string; vol: string; afgekort: boolean }

// De shapes uit de GELADEN bronnen. Zij winnen van de meegeleverde shape zodra
// hun sh:targetClass dezelfde is (forms.js).
//
// DE CACHE HANGT AAN DE GRAAF ÉN AAN `graafVersie` (14 sep 2026). Hier stond
// alleen de graaf-IDENTITEIT, met als reden "een mutatie verandert de shapes
// niet". Dat klopt voor een mutatie, maar niet voor een BIJMENGING: in
// endpointmodus komen de formulier-shapes ná de modelbouw in dezelfde store
// terecht (`mengVormShapes` in stores/corpus.ts), en met een identiteitscache
// bleef deze lijst dan voor altijd leeg — geen dekking, geen vouw, geen
// kerngegeven, terwijl de shapes in de graaf staan. Het is bovendien de
// EERLIJKER sleutel: wie een shapes-bestand als bewerkbron heeft, verandert met
// een mutatie wel degelijk de shapes.
//
// De kost is dat `readShapes` per graafversie opnieuw draait. Dat is dezelfde
// levensduur als de dekkingstabel en de shape-index hieronder, die allebei al
// via `bronShapes` over dezelfde quads liepen; gemeten op het jenv-corpus kost
// het trio samen enkele milliseconden (zie de metingen bij `shapeIndex`).
let cache: { g: Graaf; v: number; shapes: Shape[] } | null = null;

/** Alleen voor tests en voor een taalwissel-doorloop: de shape-cache vergeten. */
export function vergeetVormen(): void {
  cache = null; dekking = null; index = null; vouwen = null;
}

function bronShapes(g: Graaf): Shape[] {
  const v = graafVersie();
  if (!cache || cache.g !== g || cache.v !== v) cache = { g, v, shapes: leesShapes(g) };
  return cache.shapes;
}

/** DE MEEGELEVERDE SHAPES. Zelfde rol als de meegeleverde ODRL-labels: er is
 *  altijd een artefactformulier, ook als geen enkele bron er een meebrengt — en
 *  een shape uit de data wint ervan (`shapeForNode`/`shapeIndex` nemen ze als
 *  `fallbacks`, en een gelijke sh:targetClass uit een bron verdringt ze).
 *
 *  `builtinShapes` parst zijn TTL één keer en cachet zelf; deze functie is dus
 *  goedkoop genoeg om er per vraag langs te gaan. */
function meegeleverdeShapes(): Shape[] {
  return ingebouwd([ARTIFACT_FORM_SHAPE_TTL]);
}

/** De meegeleverde artefactshape apart — de terugval van `artefactVorm`. */
function artefactShape(): Shape | null {
  return meegeleverdeShapes()[0] || null;
}

function vorm(iri: string | null | undefined, terugval: Shape | null): FormVorm | null {
  // De graafversie meelezen houdt het formulier bij: hij komt op het worker-pad
  // ná het model binnen, en elke mutatie schuift hem op.
  void graafVersie();
  const g = graaf() as Graaf | null;
  if (!g || !iri) return null;
  const shape = shapeVoorKnoop(g, iri, bronShapes(g), meegeleverdeShapes())
    || terugval;
  if (!shape) return null;
  return bouwVorm(g, iri, shape);
}

/** Het formulier van een willekeurige domeinknoop, of `null` als geen enkele
 *  shape hem dekt. */
export function vormVoorKnoop(iri: string | null | undefined): FormVorm | null {
  return vorm(iri, null);
}

// --- IS DEZE KNOOP GEDEKT? --------------------------------------------------
//
// De vraag van de uitklap-affordance, en zij wordt héél vaak gesteld: elke
// verwezen waarde in elke rij van elke kaart wil weten of er een formulier
// achter zit. Het rekenwerk staat in `model/forms.js` (`coveredClasses`,
// `isCovered`); hier staat alleen de CACHE — de tabel hangt aan de
// graaf-identiteit én aan `graafVersie`, want een mutatie kan een
// rdfs:subClassOf of een rdf:type toevoegen.
let dekking: { g: Graaf; v: number; klassen: Set<string> } | null = null;

function dekkingVoor(g: Graaf): Set<string> {
  const v = graafVersie();
  if (dekking && dekking.g === g && dekking.v === v) return dekking.klassen;
  const klassen = gedekteKlassen(g, [...bronShapes(g), ...meegeleverdeShapes()]);
  dekking = { g, v, klassen };
  return klassen;
}

/** Dekt een FORMULIER-shape deze knoop? Goedkoop genoeg om hem per verwezen
 *  waarde te stellen; het formulier zelf wordt pas gebouwd zodra de lezer
 *  uitklapt.
 *
 *  DE MEEGELEVERDE ARTEFACTSHAPE TELT MEE (15 sep 2026). Hier stond het
 *  omgekeerde, met als reden: "een artefact heeft in deze weergave al zijn eigen
 *  plek — de uitklap op de conformsToPolicy-rij (`ArtefactVouw`) — en een tweede
 *  ingang naar hetzelfde formulier is ruis". Die eigen plek bestaat niet meer:
 *  `ArtefactVouw` wás de ODRL-AP-NL-tak in de viewerkern (een uitklap die aansloeg
 *  op de operator `apnl:conformsToPolicy`) en is vervallen op eigenaarsbesluit
 *  ("Dat klinkt als ODRL-AP-NL specifiek iets in de viewer. Dat is niet de
 *  bedoeling."). Een artefact klapt sindsdien open langs dezelfde weg als elke
 *  andere gedekte knoop, en dan moet deze vraag hem ook kennen — anders verliest
 *  élk corpus zonder eigen artefact-shape zijn artefactformulier. */
export function dektKnoop(iri: string | null | undefined): boolean {
  const g = graaf() as Graaf | null;
  if (!g || !iri) return false;
  return knoopGedekt(g, iri, dekkingVoor(g));
}

// --- HET KERNGEGEVEN OP DE DICHTE SUMMARY -----------------------------------
//
// EIGENAARSFEEDBACK 11 SEP 2026: een dichte vouw hoort te zeggen WAT erachter
// zit, niet alleen dat er iets achter zit. Dat kerngegeven (dash:KeyInfoRole)
// hangt aan de SHAPE, en de dekkingstabel kent alleen de klassen — dus is er een
// tweede, even goedkope route nodig.
//
// GEMETEN op het jenv-corpus (6 bronnen, 4.908 quads, 60 shapes, 564
// dekkingsvragen waarvan 44 gedekt, 28 met een kerngegeven):
//   kerngegeven via `shapeForNode` per knoop   55,93 ms
//   kerngegeven via `formModel` per knoop      57,69 ms
//   kerngegeven via de shape-INDEX              1,66 ms   (index bouwen: 1,36 ms)
// De index staat in `model/forms.js` en geeft per constructie hetzelfde antwoord
// als `shapeForNode` (toets op het hele corpus in `forms.test.mjs`); hier staat
// alleen de cache, met dezelfde levensduur als de dekkingstabel.
let index: { g: Graaf; v: number; ix: ShapeIndex } | null = null;

function indexVoor(g: Graaf): ShapeIndex {
  const v = graafVersie();
  if (index && index.g === g && index.v === v) return index.ix;
  // MÉT de meegeleverde shapes als terugval, in dezelfde verhouding als
  // `shapeForNode` hierboven: een bron-shape met dezelfde sh:targetClass wint.
  // Zonder hen zou `vouwVorm` voor een artefact langs de trage route moeten
  // (`vormVoorKnoop`) — 55,93 ms tegen 1,66 ms op het jenv-corpus — en zouden
  // zijn type-pil en zijn kerngegeven leeg blijven.
  const ix = bouwIndex(g, bronShapes(g), meegeleverdeShapes());
  index = { g, v, ix };
  return ix;
}

/** Het kerngegeven van een gedekte knoop, of een lege lijst. Leeg betekent
 *  LEEG: de aanroeper zet dan geen badge neer, en geen lege badge. */
export function kerngegevenVoor(iri: string | null | undefined): FormWaarde[] {
  const g = graaf() as Graaf | null;
  if (!g || !iri) return [];
  return kerngegeven(g, iri, shapeUitIndex(g, iri, indexVoor(g)));
}

/** Het formulier zonder de rijen die terugwijzen naar de knoop waaronder het
 *  hangt (eigenaarsmelding 14 sep 2026 — de "Samenhang"-dubbeling). Zonder
 *  ouder — een formulier op het TOPniveau — komt het model onveranderd terug;
 *  de reden en de afweging staan bij `dropBacklinks` in model/forms.js. */
export const zonderOuderverwijzing = dropBacklinks as unknown as (
  m: FormVorm, ouder: string | null) => FormVorm;

/** HET FORMULIER ZOALS EEN VOUW HET ONDER ZIJN KOP ZOU TONEN: de vorm van de
 *  knoop, zonder de rijen die terugwijzen naar de knoop waaronder hij hangt.
 *  `null` als geen enkele shape hem dekt.
 *
 *  ÉÉN PLEK VOOR TWEE VRAGEN (eigenaarsfeedback 14 sep 2026: "wanneer een chip
 *  geen subvelden heeft mag het wel nog als chip getoond worden maar moet het
 *  geen uitklap-chevron hebben"). De weergave moet nu vóór het openklappen weten
 *  óf er iets onder de kop komt, en ná het openklappen wat er komt. Dat mag geen
 *  twee tellingen worden die uit elkaar kunnen lopen: een chevron die verdwijnt
 *  terwijl er wél rijen zijn (of blijft staan boven een leeg lijf) is precies de
 *  oneerlijkheid die de melding aanwijst. Daarom halen beide hun antwoord uit
 *  DEZE functie. */
export function vouwVorm(
  iri: string | null | undefined, ouder: string | null,
): FormVorm | null {
  void graafVersie();
  const g = graaf() as Graaf | null;
  if (!g || !iri) return null;
  // DE SCHEIDER ALS ESCAPE EN NIET ALS RUWE BYTE (fold-correctie, 14 sep 2026).
  // NUL is de juiste scheider — hij kan in geen enkele IRI voorkomen — maar hij
  // stond hier LETTERLIJK in de bron, en dan is `grep` blind voor dit HELE bestand:
  // zwijgend, met exitcode 1 en zonder melding. Dat leest als "niet gevonden" en
  // heeft elders al twee folds diagnosetijd en een lane een halve dag gekost
  // (draaiboekregel NUL-byte-check, 9 sep). De waarde is identiek; alleen de
  // notatie verandert.
  const sleutel = iri + '\u0000' + (ouder || '');
  const c = vouwCache(g);
  const gehad = c.get(sleutel);
  if (gehad !== undefined) return gehad;
  // DE SHAPE UIT DE INDEX, niet uit `shapeForNode` (14 sep 2026, gemeten).
  // Beide geven per constructie hetzelfde antwoord — `forms.test.mjs` pint dat
  // op het hele corpus — maar `shapeForNode` doorloopt per knoop de shapelijst
  // met haar subklassesluiting, en dat is de route die het vorige report op
  // 55,93 ms voor 564 vragen mat tegen 1,66 ms via de index. Zolang deze vraag
  // pas bij het OPENklappen werd gesteld was dat verschil onzichtbaar; nu zij
  // per DICHTE vouwkop gesteld wordt, is het de helft van de rekening.
  //
  // De index kent alleen de shapes uit de BRONNEN, en dat is precies goed: een
  // knoopvouw bestaat alleen waar `dektKnoop` waar is, en die kijkt naar
  // diezelfde verzameling. `vormVoorKnoop` blijft de terugval voor het
  // onverwachte geval dat de index niets weet.
  const shape = shapeUitIndex(g, iri, indexVoor(g));
  const ruw = shape ? bouwVorm(g, iri, shape) : vormVoorKnoop(iri);
  const m = ruw ? zonderOuderverwijzing(ruw, ouder) : null;
  c.set(sleutel, m);
  return m;
}

// DE CACHE VAN DE VOUWVORMEN (14 sep 2026), en waarom hij er moet zijn.
//
// De leeg-toets vraagt per DICHTE vouwkop een formulier op; het lijf vraagt er
// even later hetzelfde nog eens, en elke reactieve herlezing van `vouwbaar()`
// zou het een derde keer doen. Zonder cache is dat het herstel na een herlading
// dat de poort `vouw-herstel-fasering` bewaakt: gemeten op `b754ded` haalde dat
// geval 30 s, met de ongecachte toets 121 s en een langste taak van 1186 ms
// tegen een budget van 1000 ms — ROOD. Met index en cache staat hij weer groen;
// de getallen staan in het report.
//
// DE SLEUTEL IS (KNOOP, OUDER), want leeg is een eigenschap van de PLEK: onder
// zijn directe ouder valt een rij weg die er op een andere plek wél staat.
//
// DE LEVENSDUUR IS DIE VAN DE DEKKINGSTABEL EN DE INDEX — graaf-identiteit plus
// `graafVersie` — MÉT ÉÉN ERBIJ: de TAAL. `formModel` kiest zijn labels via
// `pickLabel`, en een taalwissel bumpt `graafVersie` niet. Zonder die derde
// sleutel zou een vouw na het omzetten naar Engels zijn Nederlandse rijen
// blijven tonen. `vergeetVormen()` gooit hem ook weg, zodat de testhaak blijft
// werken.
let vouwen: { g: Graaf; v: number; taal: string; m: Map<string, FormVorm | null> } | null = null;

function vouwCache(g: Graaf): Map<string, FormVorm | null> {
  const v = graafVersie();
  const taal = getLang() as string;
  if (vouwen && vouwen.g === g && vouwen.v === v && vouwen.taal === taal) return vouwen.m;
  vouwen = { g, v, taal, m: new Map() };
  return vouwen.m;
}

/** LEVERT DIT MODEL IETS OP ONDER EEN VOUWKOP? Blokken óf een beschrijving: dat is
 *  letterlijk alles wat `Formulier` met `kop={false}` tekent, dus als die twee
 *  leeg zijn blijft er onder de kop geen pixel over.
 *
 *  GEMETEN op het jenv-corpus (`probe-lege-vouw.mjs` in de workspace-map, 14 sep
 *  2026): 51 gedekte knopen, `formModel` voor alle 51 samen 2,5 ms — 0,049 ms
 *  per knoop. De toets mag dus per dichte vouwkop gesteld worden zonder cache;
 *  dat is dezelfde orde als de dekkingsvraag die er al per verwezen waarde
 *  staat. Van de 69 (ouder, kind)-paren in dat corpus zijn er twee leeg, en het
 *  zijn precies de twee die de eigenaar noemt: de waardedomeinen onder hun
 *  gegevenstype. Op TOPniveau is er geen enkele — leeg ontstaat pas doordat de
 *  terugverwijzing naar de ouder wegvalt. */
export function vormHeeftInhoud(m: FormVorm | null): boolean {
  return !!m && (m.blocks.length > 0 || !!m.description);
}

/** DE DIRECTE AANHECHTKNOOP UIT EEN KETEN, of `null` op het topniveau.
 *
 *  De keten groeit in PAREN — een aanhechtPLEK (kaartrij, doelwitrij of
 *  formulierrij) en dan de KNOOP die daar hangt — dus de keten van een vouw
 *  eindigt altijd op een plek, en de knoop erboven staat er één vóór. Dat is
 *  een STRUCTURELE lezing en geen tekstherkenning: de rijschakels van 14 sep
 *  beginnen met `#` maar een kaartplek is `<knoop>#<predicaat>`, en een IRI mag
 *  zelf ook een `#` dragen — op de vorm van de string valt hier dus niets te
 *  bouwen.
 *
 *  Eén element betekent: alleen de plek, dus dit formulier hangt direct onder
 *  een kaartrij. Daar is geen ouderKNOOP om naar terug te verwijzen. */
export function directeOuder(keten: readonly string[]): string | null {
  return keten.length >= 2 ? keten[keten.length - 2] : null;
}

/** Het TYPE van een gedekte knoop, als tekst voor de pil op zijn vouwkop. Geen
 *  shape, geen pil — maar een gedekte knoop HEEFT er per definitie een, dus op
 *  een vouwkop staat de pil er altijd. Dat is precies de affordance: een pil
 *  vooraan de regel betekent "hier zit een formulier achter".
 *
 *  Dezelfde goedkope route als `kerngegevenVoor`: de shape-INDEX, niet
 *  `shapeForNode` per knoop (zie de meting hierboven). */
export function typeLabelVoor(iri: string | null | undefined): TypeLabel | null {
  const g = graaf() as Graaf | null;
  if (!g || !iri) return null;
  return typeLabel(g, shapeUitIndex(g, iri, indexVoor(g)));
}

/** Hoeveel knopen in het corpus draagt een geladen formulier-shape? De telling
 *  van de statusregel: geen enkele formulier-shape geladen, geen telling.
 *
 *  IN ENDPOINTMODUS TELT HET ENDPOINT (14 sep 2026). De clientgraaf draagt daar
 *  niet het corpus maar wat de lezer tot nu toe heeft opengeklapt; een telling
 *  daarover kruipt tijdens het lezen omhoog en zegt nooit hoe groot het geheel
 *  is. `stores/corpus.ts` haalt het getal daarom met één COUNT bij de lading op;
 *  staat het er, dan wint het. Staat het er niet (geen endpoint, of de query
 *  faalde), dan telt de weergave zoals altijd. */
export function gedekteKnopen(): number {
  const uitEndpoint = gedektTelling();
  if (uitEndpoint !== null) return uitEndpoint;
  const g = graaf() as Graaf | null;
  if (!g) return 0;
  return telGedekt(g, dekkingVoor(g));
}

/** Het formulier van een ARTEFACT. De aanroeper weet hier al dat de knoop een
 *  artefact is (het model noemde hem zo), dus de meegeleverde shape geldt ook
 *  wanneer de knoop geen passend rdf:type draagt — precies de `fallback` van
 *  `artifactForm` in de bevroren viewer. */
export function artefactVorm(iri: string | null | undefined): FormVorm | null {
  return vorm(iri, artefactShape());
}
