// DE OPEN-STAND VAN HET DOCUMENT: één administratie per bronnencorpus.
//
// Gedragsbron: `openState` / `noteToggle` / `rememberedOpen` in de bevroren
// viewer (viewer-bevroren/assets/doc.js r.11519-11547). Daar staat ALLES wat de lezer
// openzette in dezelfde set, onder dezelfde corpussleutel — een kaart op haar
// `data-iri`, en een fold-out zonder eigen identiteit (een ledenlijst, een tak
// in de partOf-boom, een "gebruikt door"-regel) op haar `data-open-key`. Die
// gedeelde set staat hier, los van de kaartenlijst, omdat er drie families op
// schrijven: de kaarten (`kaartenlijst.tsx`), de ledenboom (`leden.tsx`,
// sleutels `coll:` en `tree:`) en de terugverwijzingen (`terugverwijzingen.tsx`,
// sleutel `usedby:`).
//
// DE BEWAARDE STAND IS EEN ADMINISTRATIE, GEEN MOMENTOPNAME VAN DE DOM. Dat
// onderscheid is overgenomen en het is wezenlijk: bij een herrender staat het
// meeste niet in de DOM — de volgende chunk niet, weggefilterde kaarten niet,
// een tak die zijn niveau nog niet gebouwd heeft niet. Wie de hele voorkeur zou
// vervangen door "wat er nu open staat", wist precies wat hij moest onthouden.
// Daarom werkt elke toggle ALLEEN ZIJN EIGEN sleutel bij; de rest blijft staan.
//
// WAT HIER ANDERS IS DAN IN DE BEVROREN VIEWER: daar was het herstel een
// NABEWERKING (`restoreListUi`, in rondes, want de DOM moest eerst bestaan).
// Hier is de bewaarde stand gewoon de STARTSTAND van elk blok — een component
// die opgebouwd wordt vraagt hem op en rendert meteen open. De rondes vervallen
// daarmee: een tak die nog niet bestaat heeft niets te herstellen, en zodra hij
// gebouwd wordt leest hij zijn eigen sleutel. Wat blijft is de sleutelvorm.
import { createSignal } from 'solid-js';
import { prefGet, prefSet } from '../model/prefs.js';
import { weergave } from './weergave.js';

/** De opslagsleutel van dit corpus. Zelfde vorm als in de bevroren viewer:
 *  'open:' + de gesorteerde bronnen, met ?ttl=/?sparql= erbij — dat zijn
 *  legacy-aliassen van ?src= en horen dus in dezelfde sleutel. */
export function corpusSleutel(): string {
  const bronnen = [...weergave.src, ...weergave.ttl, ...(weergave.sparql ? [weergave.sparql] : [])];
  return 'open:' + [...bronnen].sort().join('|');
}

const [standVersie, zetStandVersie] = createSignal(0);
let standSleutel: string | null = null;
let stand: Set<string> | null = null;

function standVan(sleutel: string): Set<string> {
  if (stand === null || standSleutel !== sleutel) {
    // Andere bronnen (bron toegevoegd/verwijderd): andere administratie.
    const bewaard = prefGet(sleutel, []);
    stand = new Set<string>(Array.isArray(bewaard) ? bewaard : []);
    standSleutel = sleutel;
  }
  return stand;
}

/** Lees de administratie opnieuw uit de opslag. De set hierboven is een CACHE
 *  (hij wordt per gerenderde rij bevraagd; JSON parsen per rij zou bij 1.392
 *  kaarten merkbaar zijn) en ververst zichzelf alleen als de corpussleutel
 *  wijzigt. Wie de opslag búiten deze module om leegmaakt — een test, of een
 *  toekomstige "vergeet mijn voorkeuren"-knop — zegt dat hiermee. */
export function vergeetOpenStand(): void {
  stand = null;
  standSleutel = null;
  rijStand.clear();
  rijStandSleutel = null;
  zetStandVersie((v) => v + 1);
  zetRijVersie((v) => v + 1);
}

// --- DE VLUCHTIGE STAND: WAT DE LEZER DEZE SESSIE ZELF WISSELDE --------------
//
// CONTRACTUITBREIDING (dt3, lane-toevoegfocus, eigenaarsbesluit 8 sep 2026: "er
// mag niks anders open/dichtklappen"). Wat hierboven staat is de BEWAARDE
// voorkeur van de lezer; wat hier staat is de open-stand van de regel-, groeps-
// en plichtrijen BINNEN een kaart, en die is bewust van een andere orde.
//
// HET GEMETEN GEVAL. Een regelrij bewaarde zijn open-stand nergens: hij is een
// gewone <details> en de stand woonde in de DOM. Zolang de DOM blijft staan is
// dat genoeg — maar een mutatie in dezelfde kaart laat `corpus.ts` die kaart
// GERICHT herbouwen, en dan zijn de regelobjecten nieuw, hertekent `<For>` de
// rijen, en is de stand weg. Gemeten op de e2e-set (`toevoegfocus.mjs`, vóór de
// fix): één klik op "+ toestemming" klapte een openstaande regelrij in dezelfde
// kaart dicht — precies het "iets anders klapt dicht" van het besluit.
//
// WAAROM NIET IN DE BEWAARDE SET HIERBOVEN. Twee redenen, en de tweede is
// bindend:
//  1. de bevroren viewer bewaarde de rijstand ook niet (`openState` draagt
//     kaarten op `data-iri` en fold-outs op `data-open-key`; een regelrij heeft
//     geen van beide). Rijen zouden na een herlading ineens allemaal openstaan —
//     een gedragswijziging die niemand gevraagd heeft;
//  2. de sleutel van een VERSE regel is zijn blank-node-label (`_:b12`). Dat
//     label is stabiel binnen één sessie en betekenisloos daarbuiten: het
//     wegschrijven zou na een herlading een willekeurige andere rij openzetten.
//
// Vandaar: dezelfde vorm, dezelfde reactiviteit, maar in het geheugen en zonder
// opslag. Hij wordt met de bewaarde stand meegewist (`vergeetOpenStand`).
//
// TWEEDE GEBRUIKER, FIXRONDE 1: DE BLOKKEN MET EEN DEFAULT-STAND. Een ledenlijst
// (`coll:`) en een "gebruikt door"-blok (`usedby:`) hebben, anders dan een
// regelrij, een STANDAARDstand die van de data afhangt: onder `refListCollapsed`
// staan ze vanzelf open. Hun formule is
// `handmatig() ?? (staatOpen(sleutel) || !refListCollapsed(n))`, en `handmatig`
// was een COMPONENT-LOKAAL signaal. Dat is de derde variant van dezelfde fout:
// klapte de lezer zo'n blok expliciet dicht, dan stond die keuze nergens — de
// bewaarde set noemt immers alleen wat OPEN stond — en bij de hermontage na een
// toevoeging won de default weer. Gemeten (`toevoegfocus.mjs`, vóór de fix):
// `usedby:…set-1: false → true` en twee maal `coll:…gegevens-1: false → true`.
//
// Daarom is deze administratie DRIESTANDIG en niet booleaans: "niets gezegd"
// (de default beslist), "open" en "dicht" zijn drie verschillende dingen, en
// juist het derde was er niet. `staatRijOpen` blijft de booleaanse lezing voor
// wie geen default heeft.
const rijStand = new Map<string, boolean>();
const [rijVersie, zetRijVersie] = createSignal(0);
let rijStandSleutel: string | null = null;

/** DE VLUCHTIGE STAND HOORT BIJ HÉT CORPUS, net als de bewaarde set hierboven.
 *
 *  Gemeten toen dat er niet stond (`leden.test.tsx`, "een ander bronnencorpus is
 *  een andere administratie"): de lezer klapte een ledenlijst open onder
 *  `onthoud.ttl`, wisselde van bron, en zag hem daar weer open staan — de
 *  bewaarde set was correct per corpus gescheiden, maar deze administratie liep
 *  er dwars doorheen. Dezelfde vervaldatum dus als `standVan`: andere bronnen,
 *  andere administratie. */
function rijStandVan(): Map<string, boolean> {
  const corpus = corpusSleutel();
  if (rijStandSleutel !== corpus) {
    rijStand.clear();
    rijStandSleutel = corpus;
  }
  return rijStand;
}

/** WAT DE LEZER ZELF WISSELDE aan dit blok, of `null` als hij er niets over zei.
 *  Het antwoord van een blok MET een standaardstand: alleen `null` laat die
 *  standaard beslissen. Reactief, zoals `staatOpen`. */
export function vluchtigeStand(sleutel: string): boolean | null {
  // DE LEGE SLEUTEL LEEST HET SIGNAAL NIET, en dat is geen micro-optimalisatie.
  // Een blok zonder adres kan zijn stand nergens bewaren; zou het hier tóch op
  // `rijVersie` intekenen, dan zet de volgende toggle van een ÁNDER blok zijn
  // `open` weer terug — het blok dat je zojuist opende klapt dan dicht zodra er
  // elders iets gebeurt. De aanroeper valt in dat geval terug op zijn eigen
  // signaal (zie `ui/gedeeld/vouwstand.ts`).
  if (!sleutel) return null;
  rijVersie();
  const v = rijStandVan().get(sleutel);
  return v === undefined ? null : v;
}

/** Stond deze rij open vóór de laatste herbouw? De BOOLEAANSE lezing, voor een
 *  blok zonder standaardstand: een regelrij staat dicht tenzij de lezer hem
 *  openzette, en "niets gezegd" en "dicht" zijn daar hetzelfde. */
export function staatRijOpen(sleutel: string): boolean {
  return vluchtigeStand(sleutel) === true;
}

/** Eén rij wisselde van stand. Alleen díe sleutel — zelfde regel als hierboven:
 *  wie de hele administratie zou vervangen door "wat er nu in de DOM staat",
 *  wist de stand van elke rij die op dit moment niet getekend is (een kaart die
 *  dicht staat, een chunk die nog niet gebouwd is). */
export function zetRijOpen(sleutel: string, open: boolean): void {
  if (!sleutel) return;
  const s = rijStandVan();
  if (s.get(sleutel) === open) return;
  s.set(sleutel, open);
  zetRijVersie((v) => v + 1);
}

/** Stond dit blok bij het vorige bezoek open? Reactief op elke toggle. */
export function staatOpen(sleutel: string): boolean {
  standVersie();
  if (!sleutel) return false;
  return standVan(corpusSleutel()).has(sleutel);
}

/** Eén blok wisselde van stand: alleen díe sleutel bijwerken en wegschrijven. */
export function zetOpen(sleutel: string, open: boolean): void {
  if (!sleutel) return;
  const corpus = corpusSleutel();
  const s = standVan(corpus);
  const was = s.has(sleutel);
  if (open) s.add(sleutel); else s.delete(sleutel);
  if (s.has(sleutel) === was) return;
  prefSet(corpus, [...s]);
  zetStandVersie((v) => v + 1);
}
