// LANGE LITERALS AFKAPPEN — bevinding I-5.
//
// Een volledige licentietekst (cc:legalcode), een uitgeschreven toelichting van
// 961 tekens: die horen niet integraal in een kaartkop. De bevroren viewer kapt
// af op 600 tekens en zet er een knop "toon meer (n tekens)" achter (`longText`,
// viewer-bevroren/assets/doc.js r.394-414). Het MODEL en het bronfragment blijven
// volledig — dit is puur een weergavekwestie.
//
// Gemeten vóór deze herbouw, op breda: `button.toggle-more` 9 → 0 en
// `.longtext` 9 → 20. De nieuwe app zette de klasse op ÉLKE literal en kapte
// niets af; beschrijvingen van 642, 838, 936 en 961 tekens stonden voluit in de
// kaartkop.
//
// DE KLASSE HOORT BIJ DE AFKAPPING, niet bij "het is een literal": `.longtext`
// zet `white-space: pre-wrap`, en dat is precies wat een afgekapte, uitklapbare
// tekst nodig heeft. Een korte waarde levert daarom een kale `<span>` — zoals
// `longText` dat ook doet.
import { createSignal, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { tekst } from '../../stores/weergave.js';

/** Boven hoeveel tekens er wordt afgekapt. Letterlijk de LONG_TEXT_LIMIT van de
 *  bevroren viewer. */
export const LANGE_TEKST_GRENS = 600;

/** De afgekapte vorm: op de grens, met de staartspatie weg en een beletselteken
 *  erachter. Pure functie, zodat de pariteit los toetsbaar is. */
export function afgekapt(tekstwaarde: string): string {
  return tekstwaarde.slice(0, LANGE_TEKST_GRENS).trimEnd() + '…';
}

export function LangeTekst(props: { tekst?: string | null }): JSX.Element {
  const [open, zetOpen] = createSignal(false);
  const s = () => String(props.tekst ?? '');
  const lang = () => s().length > LANGE_TEKST_GRENS;
  return (
    <Show when={lang()} fallback={<span>{s()}</span>}>
      <span class="longtext">
        <span>{open() ? s() : afgekapt(s())}</span>
        {' '}
        <button
          type="button" class="toggle-more"
          aria-expanded={open() ? 'true' : 'false'}
          onClick={() => zetOpen((v) => !v)}
        >
          {open() ? tekst('text.showLess') : tekst('text.showMore', { n: s().length })}
        </button>
      </span>
    </Show>
  );
}
