// HET DOMEINFORMULIER ALS WEERGAVE — `formBox` uit de bevroren viewer.
//
// Gedragsbron: `formBox`, `formValues`, `formValueNode`, `formLabel` en
// `longToken` in `viewer-bevroren/assets/doc.js` (r.8866-9100). Het weergavemodel komt
// kant-en-klaar uit `formulier-model.ts`; wat hier staat is uitsluitend VORM —
// welke klasse een waarde draagt, wanneer zij een link wordt, en waar de
// eerlijkheidsnoot terechtkomt.
//
// DE 7×5-KV-DELTA VAN DE dt2-EINDDOORLOOP WORDT HIER INGELOST. Die doorloop mat
// op breda `Programmeertaal 5 -> 0` en `Soort 5 -> 0` en noemde zeven labels
// (Programmeertaal, Soort, Broncode, Download, Entrypoint, Formaat, sha256) die
// met `artifactForm` waren blijven liggen. Ze horen bij deze component: de
// nieuwe app had wél de conformsToPolicy-rij, maar niets om onder haar uit te
// klappen.
//
// ÉÉN AFWIJKING VAN DE BEVROREN VIEWER, en zij is de bestaande afspraak van dt2:
// de UITLEG bij een veldlabel (sh:description, met de definitie van het
// pad-predicaat als terugval) staat hier als `data-desc` op de `<dt>` en niet
// als tooltip-paneeltje. Zo doen de slot-chips van een voorwaarde het ook sinds
// dt2; de taak die de tooltip herbouwt haakt op dezelfde plek aan.
import {
  For, Show, createContext, createEffect, createMemo, createSignal, lazy, useContext,
} from 'solid-js';
import type { JSX } from 'solid-js';
import { endpoint, haalKnoopVorm } from '../../stores/corpus.js';
import { staatOpen, zetOpen } from '../../stores/openstand.js';
import { tekst, weergave } from '../../stores/weergave.js';
import { Chevron } from '../gedeeld/chip.jsx';
import { Kv } from '../gedeeld/kop.jsx';
import type { KvRij } from '../gedeeld/kop.jsx';
import { kopBediening } from '../gedeeld/kopselectie.js';
import { LangeTekst } from '../gedeeld/langetekst.jsx';
import { veiligeHref } from '../gedeeld/veilige-link.js';
import {
  dektKnoop, directeOuder, kerngegevenVoor, typeLabelVoor, vormHeeftInhoud, vouwVorm,
} from './formulier-model.js';
import { herstelLater } from './herstelwachtrij.js';
import type { FormRij, FormVorm } from './formulier-model.js';
import './formulier.css';

// De BEWERKKANT, apart gebundeld. `lazy` haalt hem pas op als de bewerkstand
// voor het eerst aan gaat; tot dan staat er niets van in de leeschunk (spec §1)
// — zelfde vorm als `Bronnenmutaties` in `ui/app/bronnen.tsx`.
const FormulierRijBewerk = lazy(() => import('./formulier-bewerk.jsx'));

// Eén lang token (een hash, een URL zonder spaties) mag overal afbreken, anders
// duwt hij de kolom uit beeld. Zuiver presentatie, geen vocabulaire.
const LANG_TOKEN = 40;
const langToken = (t: string): boolean => String(t).length >= LANG_TOKEN && !/\s/.test(t);

/** De tekst van één waarde. Drie vormen, precies zoals `formValueNode`:
 *
 *  - `link` (dash:URIViewer): de IRI zelf als link naar buiten;
 *  - `label` (dash:LabelViewer): DASH omschrijft die als "a hyperlink to that
 *    URI based on the display label" — linktekst het label, bestemming de IRI.
 *    Alleen voor een knoop die BUITEN het geladen corpus ligt: interne IRI's
 *    staan in deze viewer nergens als naakte link, want daarvoor is de weergave
 *    zelf de plek. En alleen voor een schema dat een browser kan volgen;
 *  - anders gewone tekst, in mono wanneer de shape een `sh:pattern` opgaf (de
 *    waarde heeft dan een machinesyntaxis) en met `.hash` wanneer zij één lang
 *    ononderbroken token is. */
export function FormulierWaarde(props: {
  v: FormRij['values'][number]; mono?: boolean;
}): JSX.Element {
  const v = () => props.v;
  const klasse = () => [props.mono ? 'mono' : '', langToken(v().text) ? 'hash' : '']
    .filter(Boolean).join(' ');
  // HET ADRES DAT DEZE WAARDE ZOU WORDEN — of `null` als het geen linkbaar
  // schema draagt. De `label`-tak toetste dat al (`/^https?:/`); de `link`-tak
  // (dash:URIViewer, o.a. `dcat:downloadURL` en `dct:source` op een artefact)
  // zette de waarde NAAKT in de href, en een IRI uit een bron mag elk schema
  // dragen — `<javascript:…>` is geldige Turtle. Nu geldt één regel voor beide.
  const adres = () => veiligeHref(v().kind === 'link' ? v().text : v().iri);
  return (
    <Show
      when={v().kind === 'link' || (v().kind === 'label' && v().external)
        ? adres()
        : null}
      fallback={(
        <Show when={klasse()} fallback={<span>{v().text}</span>}>
          <span class={klasse()}>{v().text}</span>
        </Show>
      )}
    >
      {(h) => <a href={h()} target="_blank" rel="noopener">{v().text}</a>}
    </Show>
  );
}

/** De waarden van één rij.
 *
 *  MEERWAARDIG -> ELKE WAARDE EEN EIGEN CHIP (besluit eigenaar, aug 2026). Een
 *  opsomming op één regel ("Soort: SoftwareSourceCode, Cedar-policyset") leest
 *  als één lange waarde — dezelfde klacht die bij de rechterwaarde van een
 *  voorwaarde al is opgelost, dus dezelfde oplossing. GENERIEK, want het is een
 *  eigenschap van het AANTAL waarden en niet van het widget-type.
 *
 *  ENKELVOUDIG BLIJFT TEKST: één waarde in een chip zou een rustige veldrij in
 *  een badge veranderen zonder dat er iets te onderscheiden valt. */
export function FormulierWaarden(props: { rij: FormRij }): JSX.Element {
  const mono = () => !!props.rij.pattern;
  // DOORKLIK IN DE DIEPTE. Wijst een waarde van deze rij zelf naar een gedekte
  // knoop (leverset → distributie → veld), dan krijgt zij dezelfde uitklap als
  // de rij op de kaart. De rij gaat dan van kommatekst naar een STAPEL: een
  // uitklapkop leest niet als een woord in een opsomming, en een `<details>`
  // hoort niet binnen de chip-regel. Wijst er niets naar een gedekte knoop —
  // het gewone geval, en het énige geval zonder profiel-shapes — dan blijft de
  // rij letterlijk wat zij was.
  const gedekt = () => props.rij.values.some((v) => v.iri && dektKnoop(v.iri));
  // DE RENDERPLEK VAN DEZE RIJ (opruimpunt 66, 14 sep 2026). De keten hierboven
  // draagt de KNOPEN waar deze rij onder hangt; wat zij niet droeg is WELKE RIJ
  // van het formulier erboven hierheen wees. Op het jenv-corpus is dat geen
  // theorie: `leverset-nazorg` wijst met «Voldoet aan» én met «Onderdeel van»
  // naar dezelfde `gls-nazorg`, en die twee vouwen kregen daarmee letterlijk
  // dezelfde sleutel. Eén klik zette ze allebei open na een herlading — de
  // restfactor 2× die na de plek-fix overbleef, en per meting de WORTEL van
  // alle 21 gespiegelde sleutels op dat corpus (elke afstammeling erfde de
  // dubbele plek van zijn ouder).
  //
  // HET IS DEZELFDE INGREEP ALS OP DE KAART, één niveau dieper. `body-rijen.tsx`
  // zet `<knoop>#<predicaat>` als aanhechtplek van een KAARTrij; dit is dat
  // predicaat voor een FORMULIERrij. `^` erachter als de rij omgekeerd gelezen
  // wordt: `sh:path` is dan hetzelfde predicaat in de andere richting, en dat
  // zijn twee rijen en dus twee plekken.
  //
  // GEEN IRI VAN EEN GEDEKTE KNOOP — de schakel begint met `#`, dus de cyclusrem
  // (`keten.includes(iri)`) raakt hem nooit; zie `KnoopKeten` hieronder. Zonder
  // die eigenschap zou een extra schakel de cyclusbewaking stilletjes verzwakken.
  const keten = useContext(KnoopKeten);
  const rijPlek = () => `#${props.rij.path || props.rij.label}${props.rij.inverse ? '^' : ''}`;
  return (
    <Show when={!gedekt()} fallback={(
      <div class="knoop-vouwen">
        <KnoopKeten.Provider value={[...keten, rijPlek()]}>
          <For each={props.rij.values}>{(v) => (
            <KnoopVouw iri={v.iri}><FormulierWaarde v={v} mono={mono()} /></KnoopVouw>
          )}</For>
        </KnoopKeten.Provider>
      </div>
    )}
    >
    <Show
      when={props.rij.values.length > 1}
      fallback={(
        <span>
          <For each={props.rij.values}>{(v) => <FormulierWaarde v={v} mono={mono()} />}</For>
        </span>
      )}
    >
      <span class="c-chips">
        <For each={props.rij.values}>{(v, i) => (
          <>
            {/* De spatie tussen de waarde-chips (eigenaarsbesluit 8 sep 2026):
                zonder tekstknoop plakt een gekopieerde formulierrij als "abc"
                in plaats van "a b c". Zie `ChipRuimte` in
                `voorwaarde-inhoud.tsx` voor het waarom; hier staat hij
                LETTERLIJK, want dit bestand is een eigen lazy chunk en één
                import naar die LEESmodule maakt haar tot gedeelde chunk (dan
                laadt de leesinstap een script en een stylesheet extra). */}
            <Show when={i() > 0}><span class="c-ruimte"> </span></Show>
            <span class="c-slot right"><FormulierWaarde v={v} mono={mono()} /></span>
          </>
        )}</For>
      </span>
    </Show>
    </Show>
  );
}

// --- DE GEDEKTE KNOOP ALS SUBKAART ------------------------------------------
//
// Een beleid verwijst naar knopen die de kaartweergave niet kent — bij het
// JenV-profiel de hele GLS-laag (dataproduct, leversets, distributies,
// gegevensvelden, afspraken) en de rol-objecten. Het MECHANISME om ze te tonen
// stond er al (`model/forms.js` leest formulier-shapes uit de geladen bronnen);
// wat ontbrak was de OPPERVLAKTE. Wijst een rij naar een knoop die een geladen
// formulier-shape dekt, dan klapt zij nu uit naar het formulier van die knoop —
// dezelfde vorm als `ArtefactVouw`, met dezelfde open-stand-regels.
//
// DRIE REGELS, en elk kost iets als je hem laat vallen:
//
//  1. NIETS VOORUIT RENDEREN. Het formulier wordt pas gebouwd zodra de vouw
//     openstaat (`<Show when={open()}>`), precies als bij `ArtefactVouw`. Zeven
//     GLS-afspraken die elk hun eigen formulier oplossen terwijl niemand ze ziet
//     is de kost die de brief "twintig afspraakknopen mogen de kaart niet
//     verdrinken" noemt. Gemeten op het jenv-corpus (zie `model/forms.js`):
//     564 dekkingsvragen samen 1,5 ms, één opengeklapt GLS-formulier 1,33 ms —
//     de affordance kost dus minder dan één vouw die de lezer écht opent.
//  2. NIETS KLAPT VANZELF OM. De startstand komt uit `staatOpen` — de bewaarde
//     administratie van dit corpus — en elke toggle schrijft alleen zijn eigen
//     sleutel terug. Een herrender (taalwissel, mutatie, filter) laat de open
//     vouwen dus open en de dichte dicht.
//  3. EEN KETEN KAN NIET IN ZICHZELF ZAKKEN. GLP → GLS → GLP is in het
//     jenv-voorbeeld een ECHTE cykel (`jenvgd:gegevensleveringsspecificatie`
//     heen, `jenvgd:gegevensleveringsprotocol` terug). Zonder rem klapt de lezer
//     zich daar oneindig diep in. De keten van voorouders reist mee in een
//     context; staat de knoop er al in, dan blijft de rij een gewone rij.
//
// DE DIEPTE ZELF IS NIET BEGRENSD (ruling): leverset → distributie → afspraak is
// drie niveaus onder de kaartrij en dat is precies de keten die de eigenaar wil
// kunnen volgen. Wat de kaart beschermt is niet een getal maar het feit dat élk
// niveau een eigen klik kost.
// DE KETEN BEGINT BIJ DE PLEK, niet bij de eerste knoop (14 sep 2026, tweede
// helft van dezelfde reparatie). De voorouderlijst draagt IRI's, en dezelfde
// IRI-keten wordt op het jenv-corpus door VIJF verschillende kaartrijen
// gerenderd: `leverset-nazorg` staat als waarde op vijf plekken, en onder elk
// van die vijf hangt letterlijk dezelfde keten. Met alleen de IRI-keten dragen
// die vijf subbomen dus nog steeds één sleutelverzameling.
//
// GEMETEN (14 sep, e2e `vouw-expansie` in zijn eerste vorm): tien klikken, tien
// open vouwen in de sessie — maar na een herlading 95, omdat elk van de tien
// bewaarde sleutels op vijf tot tien DOM-plekken paste. De sessie zag het niet,
// want `KnoopVouwOpen` leest `staatOpen` alleen bij zijn GEBOORTE; de herlading
// bouwt alles opnieuw en dan slaat elke match toe.
//
// Daarom zet elke AANHECHTPLEK een eigen eerste schakel in de keten: de knoop
// waarop de rij staat plus het predicaat van die rij (`body-rijen.tsx`), of de
// regel plus `#target` (`regels.tsx`). Die schakel is geen IRI van een gedekte
// knoop, dus de cyclusrem (`keten.includes(iri)`) raakt hem nooit — hij doet
// alleen wat hij moet doen: van elke plek een eigen administratie maken.
export const KnoopKeten = createContext<readonly string[]>([]);

/** Het formulier van een gedekte knoop, uitklapbaar onder de regel die ernaar
 *  verwijst. Is de knoop niet gedekt (of zit hij al in de keten), dan rendert
 *  deze component letterlijk zijn kind en verandert er geen pixel. */
export function KnoopVouw(props: { iri: string | null | undefined; children: JSX.Element }): JSX.Element {
  const keten = useContext(KnoopKeten);
  const iri = () => props.iri || '';
  const dekt = () => !!iri() && !keten.includes(iri()) && dektKnoop(iri());
  // DE OPEN-SLEUTEL DRAAGT DE PLEK, niet alleen de knoop. Dezelfde GLS staat op
  // de GLP-kaart én (via de leverset) een niveau dieper; met alleen de IRI als
  // sleutel zouden die twee vouwen elkaars stand overnemen en samen open- en
  // dichtklappen.
  //
  // DE HELE KETEN, NIET ALLEEN DE OUDER (eigenaarsmelding 14 sep 2026). Hier
  // stond `<ouder>><knoop>`: het PAAR. Dat is één ouder te weinig zodra die
  // ouder zelf op twee plekken in de boom staat — dan dragen zijn twee kinderen
  // dezelfde sleutel, en klapt de lezer er één open, dan wordt de ander OPEN
  // GEBOREN (`createSignal(staatOpen(sleutel))` hieronder). Die tweede rendert
  // zijn eigen kinderen, daar zitten weer bewaarde paren tussen, en zo groeit
  // de boom door zonder dat er nog geklikt wordt. Geen cykel — de cyclusrem
  // kijkt naar KNOOP-herhaling binnen één pad en ziet paar-herhaling over
  // takken heen per constructie niet.
  //
  // GEMETEN op het jenv-corpus (14 sep 2026): 818 open-acties leverden 3.233
  // open vouwen op, en de bewaarde stand groeide mee — onder één corpussleutel
  // in localStorage, dus ook in het volgende tabblad. Dat is de gemeenschappelijke
  // oorzaak van alle drie de meldingen: de trage her-open, "This page is slowing
  // down Firefox" na een reload, en het tabblad dat niet meer laadt.
  //
  // De keten staat hier al (zij is de cyclusrem), dus de plek is gratis: één
  // sleutel is vanaf nu precies één plek in de boom, en het herstel zet terug
  // wat er geklikt is en niets anders.
  const sleutel = () => 'vorm:' + [...keten, iri()].join('>');
  return (
    <Show when={dekt()} fallback={props.children}>
      <KnoopVouwOpen iri={iri()} sleutel={sleutel()} keten={keten}>{props.children}</KnoopVouwOpen>
    </Show>
  );
}

/** DE VOUW ONDER EEN HELE RIJ — hetzelfde mechanisme, ander idioom.
 *
 *  WAAROM ER TWEE IDIOMEN ZIJN (15 sep 2026, eigenaarsverzoek). Een gedekte
 *  knoop die als WAARDE in een formulierrij of op een doelwit staat, wordt zélf
 *  een chip met een kop en een lijf: dat is `KnoopVouw` hierboven. Een gedekte
 *  knoop die de rechterwaarde van een VOORWAARDERIJ is, kan dat niet worden —
 *  de rij is een zin van drie chips plus haar twee uitgangen, en een vouw om één
 *  chip heen zou haar lijf midden tussen de chips openklappen. Eigenaar:
 *  "Idealiter zou dan een chevron op de chip staan en wordt de chip, op dezelfde
 *  lokatie blijvend, dan de kop van de uitklap-chip eronder."
 *
 *  Dus: de `<details>` spant de HELE rij (`.c-fold` is `flex: 1 1 100%`), de
 *  summary is de rij zelf, en de aanroeper zet de chevron op de chip waar hij
 *  bij hoort. Alles daaronder — de open-sleutel met de plek-keten, de
 *  herstelfasering, de endpoint-hop, de leeg-toets en het lijf — is letterlijk
 *  hetzelfde als bij `KnoopVouw`, en staat daarom in dezelfde component.
 *
 *  Dekt geen shape deze knoop (het gewone geval, en élk geval zonder
 *  profiel-shapes), dan rendert deze component de kopregel zonder chevron en is
 *  de rij letterlijk wat zij was. */
export function RijVouw(props: {
  iri: string | null | undefined;
  /** De inhoud van de kopregel. Krijgt de chevron mee om hem zelf op de juiste
   *  chip te zetten, of `null` wanneer deze rij geen vouw wordt. */
  kop: (chevron: JSX.Element | null) => JSX.Element;
}): JSX.Element {
  const keten = useContext(KnoopKeten);
  const iri = () => props.iri || '';
  const dekt = () => !!iri() && !keten.includes(iri()) && dektKnoop(iri());
  const sleutel = () => 'vorm:' + [...keten, iri()].join('>');
  return (
    <Show when={dekt()} fallback={props.kop(null)}>
      <KnoopVouwOpen iri={iri()} sleutel={sleutel()} keten={keten} rijKop={props.kop} />
    </Show>
  );
}

/** De vouw zelf. Apart van `KnoopVouw` omdat het open-signaal pas mag ontstaan
 *  als vaststaat DAT er een vouw is — een `createSignal` in een tak die niet
 *  gerenderd wordt, is in Solid een signaal dat nooit meer opruimt. */
function KnoopVouwOpen(props: {
  iri: string; sleutel: string; keten: readonly string[]; children?: JSX.Element;
  /** HET RIJ-IDIOOM (zie `RijVouw`). Staat hij er, dan is deze functie de
   *  kopregel en spant de vouw de hele rij; staat hij er niet, dan is het de
   *  chip-vouw van `KnoopVouw`. */
  rijKop?: (chevron: JSX.Element | null) => JSX.Element;
}): JSX.Element {
  // DE STARTSTAND, en of die uit de BEWAARDE administratie komt. Dat onderscheid
  // is het hele verschil tussen een klik en een herstel: een klik is één vouw en
  // hoort meteen te gebeuren, een herstel zijn er honderdenveertig tegelijk.
  const hersteld = staatOpen(props.sleutel);
  const [open, zetOpenStand] = createSignal(hersteld);
  // GEFASEERD HERSTEL (opruimpunt 67, 14 sep 2026). Zie `herstelwachtrij.ts`
  // voor de meting en het mechanisme: een open geboren vouw die zijn body
  // meteen rendert, rendert daarmee ook de vouwen eronder, die óók open geboren
  // worden — het hele herstel hing zo aan één synchrone taak van 11.467 ms.
  // De `<details>` staat vanaf het eerste beeld open; alleen zijn INHOUD wacht
  // op zijn slice. Wie zelf klikt, wacht nergens op (zie `onToggle`).
  const [gebouwd, zetGebouwd] = createSignal(!hersteld);
  let el: HTMLDetailsElement | undefined;
  if (hersteld) herstelLater({ el: () => el, bouw: () => zetGebouwd(true) });
  // PAY-PER-OPEN IN ENDPOINTMODUS (eigenaarsmelding 14 sep 2026).
  //
  // In ?sparql=-modus draagt de clientgraaf het corpus niet: van deze knoop
  // staan er hooguit een rdf:type en een label in (genoeg voor de affordance
  // hierboven), en het formulier zou dus als lege kaart openen. De sluiting die
  // hij nodig heeft komt daarom bij het OPENEN — één CONSTRUCT per vouw, en
  // niets vooruit. Dat is precies het tweefasige idioom dat de kaart en de
  // ledenboom al kennen (`haalDetail`, `haalCollectieNiveau`), met dezelfde
  // administratie in de store: één keer per knoop, dichtklappen en opnieuw
  // openen kost geen tweede hop.
  //
  // In bestandsmodus doet dit niets: `haalKnoopVorm` valt zonder endpoint
  // meteen terug op `false`, `bezig` gaat niet aan, en er verandert geen pixel.
  //
  // DE HOP HANGT AAN `open()` EN NIET AAN `gebouwd()` (samenvoeging met de
  // herstelfasering, 14 sep 2026). Een vouw die uit de bewaarde stand open komt,
  // wacht op zijn slice voordat hij zijn formulier TEKENT — maar de sluiting mag
  // intussen al onderweg zijn: zij loopt over het net en niet over de
  // hoofddraad, dus zij kost de fasering niets en is er eerder door binnen.
  const [bezig, setBezig] = createSignal(false);
  // IS DE HOP GEWEEST? Alleen daarna is in endpointmodus te zeggen wat deze
  // knoop te bieden heeft; zie `vouwbaar` hieronder.
  const [gehopt, zetGehopt] = createSignal(false);
  createEffect(() => {
    if (!open() || !endpoint()) return;
    setBezig(true);
    void haalKnoopVorm(props.iri).finally(() => { setBezig(false); zetGehopt(true); });
  });
  // HET KERNGEGEVEN OP DE DICHTE KOP (eigenaarsfeedback 11 sep 2026): vóór het
  // openen al zien wát erachter zit. Leeg blijft leeg — een badge zonder inhoud
  // zegt minder dan geen badge.
  const kenmerk = () => kerngegevenVoor(props.iri).map((v) => v.text).join(' ');
  // HET TYPE OP DE KOP, ALS PIL (eigenaarswens 14 sep 2026): "Het is nu niet
  // altijd duidelijk wat uitklikbaar is en wat niet." Een gedekte knoop heeft
  // per definitie een shape, dus deze pil staat op ÉLKE vouwkop en op geen
  // enkele gewone rij — dat is wat hem tot affordance maakt en niet tot
  // versiering. De tekst komt uit het profiel (`typeLabelVoor`): de afkorting
  // als die er is, anders de volle naam; het title-attribuut schrijft de
  // afkorting uit. Zie `formulier.css` voor waarom hij NEUTRAAL gekleurd is.
  const type = () => typeLabelVoor(props.iri);
  // WAT ER ONDER DE KOP KOMT, uit één bron — de formulier-opbouw zelf, mét het
  // ouderfilter dat het lijf straks ook toepast. Zie `vouwVorm` in
  // `formulier-model.ts`: twee aparte tellingen zouden uit elkaar kunnen lopen,
  // en dan liegt de chevron.
  // ALS `createMemo`, EN DAT IS GEMETEN (14 sep 2026). Met een kale pijlfunctie
  // werd `vouwVorm` bij het herstel van twintig vouwen 81.174 keer aangeroepen —
  // 1.532 keer per vouwkop, want zowel `vouwbaar()` als het lijf leest hier
  // binnen en elke tracked herlezing doet dat opnieuw. Het REKENWERK ving de
  // cache in `formulier-model.ts` al (54 bouwsels, 13 ms op dat scenario); wat
  // een memo eraf haalt is de reactieve overhead van die 81.174 lezingen.
  const vorm = createMemo(() => vouwVorm(props.iri, directeOuder(props.keten)));
  // GEEN CHEVRON ZONDER INHOUD (eigenaarsfeedback 14 sep 2026: "wanneer een chip
  // geen subvelden heeft mag het wel nog als chip getoond worden maar moet het
  // geen uitklap-chevron hebben — substantief waardedomein Waardedomein
  // burgerservicenummer bijvoorbeeld"). De knoop HOUDT zijn chip — type-pil,
  // naam, kerngegeven — maar wordt geen `<details>`: geen chevron, geen
  // cursor: pointer, geen focus- en toetsenbordbelofte die niets inlost.
  //
  // WAAROM DIT PAS NA HET OUDERFILTER LEEG WORDT. Op het jenv-corpus heeft geen
  // enkele gedekte knoop een leeg formulier op zichzelf; leeg ontstaat doordat
  // de enige rij van de knoop terugwees naar de kop waar hij onder hangt (het
  // waardedomein onder zijn gegevenstype zegt alleen "waardedomein van: dat
  // gegevenstype"). Precies daarom is `directeOuder` hier niet optioneel.
  //
  // RULING — IN ENDPOINTMODUS BLIJFT DE CHEVRON STAAN TOT DE HOP IS GEWEEST.
  // Daar draagt de clientgraaf van deze knoop niet meer dan een rdf:type en een
  // label; het formulier komt pas met de CONSTRUCT bij het openklappen binnen
  // (zie de effect hierboven). Vooraf beslissen op wat er al client-side staat
  // zou dus élke endpointvouw haar chevron afnemen, terwijl er wél iets achter
  // zit — de duurste van de twee fouten. De chevron DOET daar bovendien iets:
  // hij haalt de sluiting op. Zodra die binnen is telt de gewone regel weer, en
  // een knoop die ook ná de hop niets oplevert verliest zijn chevron alsnog.
  //
  // GEEN MODEL IS GEEN LEEG MODEL: zolang `vouwVorm` `null` teruggeeft (de graaf
  // is er nog niet, of geen shape dekt deze knoop) blijft de vouw vouwbaar.
  // Anders zou élke vouw bij de opbouw eerst plat verschijnen en daarna alsnog
  // tot `<details>` promoveren — een tweede opbouw van de hele boom.
  const inhoudBekend = () => !endpoint() || gehopt();
  const vouwbaar = createMemo(() => {
    if (!inhoudBekend()) return true;
    const m = vorm();
    return m === null || vormHeeftInhoud(m);
  });
  // De kopregel, letterlijk dezelfde in beide standen — alleen de chevron en de
  // `<summary>` eromheen verschillen.
  const kopInhoud = () => (
    <>
      <Show when={type()}>
        {(t) => (
          <>
            <span class="method knoop-type" title={t().afgekort ? t().vol : undefined}>
              {t().text}
            </span>
            {/* Dezelfde LETTERLIJKE spatie als tussen waarde en kenmerk
                hieronder: de `gap` van de kopregel komt niet mee in het
                klembord, en dan plakt de kop als "GLSGLS detentie-einde…". */}
            <span class="c-ruimte"> </span>
          </>
        )}
      </Show>
      <span class="knoop-regel">{props.children}</span>
      <Show when={kenmerk()}>
        {/* De spatie tussen waarde en kenmerk staat er LETTERLIJK, om
            dezelfde reden als tussen de waarde-chips hierboven: een CSS-gap
            komt niet mee in het klembord, en dan plakt de kop als
            "…VlierdamGLS-JUSTID-VLD-2026-001". */}
        <span class="c-ruimte"> </span>
        <span class="chip type knoop-kenmerk">{kenmerk()}</span>
      </Show>
    </>
  );
  return (
    <Show
      when={vouwbaar()}
      fallback={(
        /* NIETS TE VOUWEN. In het RIJ-idioom is dat letterlijk de rij zonder
           chevron: zij heeft geen eigen omlijning en geen eigen kopvorm, want
           zij ís de rij (zie `RijVouw`).

           DE PLATTE CHIP van het knoop-idioom: dezelfde omlijning en dezelfde
           kopregel, zonder uitklapgedrag. Een `<div>` en geen `<summary>` — de
           semantiek moet meeveranderen, anders belooft de
           toegankelijkheidsboom nog steeds een uitklap. Hij draagt wél
           `knoop-fold`, zodat de chip-lijn, de doelwit-marge en de
           stapelruimte er zonder tweede regel op landen. */
        <Show when={props.rijKop} fallback={(
          <div class="knoop-fold knoop-fold-plat" data-knoop={props.iri}>
            <div class="knoop-summary knoop-kop-plat">{kopInhoud()}</div>
          </div>
        )}
        >{(k) => k()(null)}</Show>
      )}
    >
    {/* ALS FUNCTIE EN NIET ALS KALE JSX, en dat is een GEMETEN valkuil van Solid
        (14 sep 2026). `Show` leest een JSX-kind BINNEN zijn eigen memo, dus elk
        signaal dat tijdens het bouwen van deze `<details>` gelezen wordt —
        `open()` voorop — wordt een afhankelijkheid van die memo. Eén omklap
        bouwde daarmee de hele vouw opnieuw op, recursief. Met een functie-kind
        wikkelt `Show` de aanroep in `untrack` en blijft het element staan.
        Gemeten op het herstelscenario van twintig vouwen (`probe-vouw-herstel.mjs`
        in de workspace-map): langste taak mediaan 934 ms met een JSX-kind,
        terug naar de orde van de vóór-stand met dit functie-kind. */}
    {(_aan) => (
    <details
      ref={el}
      class={props.rijKop ? 'c-fold rij-fold' : 'c-fold knoop-fold'}
      data-open-key={props.sleutel}
      data-knoop={props.iri}
      open={open()}
      onToggle={(e) => {
        const aan = e.currentTarget.open;
        // EEN KLIK WACHT NIET OP DE WACHTRIJ. Klapt de lezer een vouw open die
        // nog op zijn slice stond, dan is dat geen herstel meer maar een
        // handeling — en een handeling die een lege body oplevert is stuk.
        zetGebouwd(true);
        zetOpenStand(aan);
        zetOpen(props.sleutel, aan);
      }}
    >
      {/* `data-art` OP DE KOPREGEL VAN EEN RIJVOUW, en niet op de `<details>`:
          een sprong hoort op de RIJ te landen, en de summary blijft zichtbaar
          als de vouw dicht is. Dat was de afspraak van `ArtefactVouw` en zij
          blijft gelden — het invulling-paneel zoekt een artefact langs dit
          attribuut terug (`refDoelen` in invulling.tsx). */}
      <summary
        class={props.rijKop ? 'vl-summary rij-summary' : 'vl-summary knoop-summary'}
        data-art={props.rijKop ? props.iri : undefined}
        {...kopBediening()}
      >
        <Show when={props.rijKop} fallback={<>{kopInhoud()}<Chevron klein /></>}>
          {(k) => k()(<Chevron klein />)}
        </Show>
      </summary>
      <div class={props.rijKop ? 'c-fold-body rij-fold-body' : 'c-fold-body knoop-fold-body'}>
        <Show when={open()}>
          {/* DE LAADREGEL, en zij staat BOVEN het formulier in plaats van
              ervoor in de plaats. Een gedekte knoop heeft per definitie een
              shape, dus `vormVoorKnoop` levert altijd een formulier — alleen
              is het zonder de sluiting nog leeg. De regel zegt dus niet "er is
              niets" maar "er komt nog iets", en verdwijnt zodra de hop binnen
              is. Zelfde afweging als `stand()` in de ledenboom.

              ZIJ HANGT AAN `open()` EN NIET AAN `gebouwd()`: een vouw die op
              zijn slice wacht, hoort te zeggen dat er iets komt. */}
          <Show when={bezig()}>
            <p class="muted knoop-laden">{tekst('vorm.loading')}</p>
          </Show>
          {/* EN HET FORMULIER ZELF WACHT OP ZIJN SLICE (opruimpunt 67). Alleen
              deze tak is gefaseerd; alles erboven staat er vanaf het eerste
              beeld. */}
          <Show when={gebouwd()}>
            <Show when={vorm()}>
              {(m) => (
                <KnoopKeten.Provider value={[...props.keten, props.iri]}>
                  {/* GEEN TERUGVERWIJZING NAAR DE KOP WAAR JE ZOJUIST OP KLIKTE
                      (eigenaarsmelding 14 sep 2026): het LGM onder de GLS zei
                      onder «Samenhang → Gebruikt door» nog eens dat het bij die
                      GLS hoort. De afweging — alleen de DIRECTE ouder, lege
                      rijen en lege groepen verdwijnen mee — staat bij
                      `dropBacklinks` in model/forms.js; welke knoop dat is,
                      staat bij `directeOuder`. */}
                  {/* EN DE TITELKOP BLIJFT WEG (eigenaarsmelding 14 sep 2026:
                      "Als je een chip uitklapt krijg je momenteel 2x de titel
                      te zien"). De vouwKOP draagt de naam én het kerngegeven al
                      — dat is het besluit van 11 sep — dus zou het formulier ze
                      er letterlijk onder herhalen.

                      VIA DE BESTAANDE PROP en niet via CSS: `display: none`
                      laat de tekst in het klembord en in de
                      toegankelijkheidsboom staan, en dan is de dubbeling voor
                      een schermlezer nog steeds een dubbeling. `kop={false}` is
                      waar deze prop voor bestaat (zie `Formulier`).

                      DE BESCHRIJVING BLIJFT: die staat NIET op de vouwkop. */}
                  <Formulier m={m()} term={props.iri} kop={false} />
                </KnoopKeten.Provider>
              )}
            </Show>
          </Show>
        </Show>
      </div>
    </details>
    )}
    </Show>
  );
}

/** De tekst van een ONGEGROEPEERDE rij (de eerlijkheidsnoot): alle waarden
 *  achter elkaar, want een alinea kent geen chips. */
const alsAlinea = (rij: FormRij): string => rij.values.map((v) => v.text).join(', ');

/** Wijst deze ONGEGROEPEERDE rij naar een gedekte knoop? Zo ja, dan is zij geen
 *  vrije tekst maar een verwijzing, en krijgt zij de uitklap in plaats van de
 *  alinea-vorm. */
const ongegroepeerdeVerwijzing = (rij: FormRij): boolean => rij.kind === 'row'
  && rij.values.some((v) => v.iri && dektKnoop(v.iri));

/** Eén rij-waarde, in de stand die er nu is. In de kijkstand is dat precies wat
 *  de weergave altijd al toonde; in de bewerkstand komt de bewerkkant ervoor in
 *  de plaats — mét de actiestrook, die de rij zelf niet kent. */
function Rijwaarde(props: {
  rij: FormRij; term?: string | null; meerregelig?: boolean;
}): JSX.Element {
  const kale = () => (props.meerregelig
    ? <LangeTekst tekst={alsAlinea(props.rij)} />
    : <FormulierWaarden rij={props.rij} />);
  return (
    <Show when={weergave.editMode && props.term} fallback={kale()}>
      <FormulierRijBewerk
        rij={props.rij}
        term={props.term as string}
        meerregelig={props.meerregelig}
      />
    </Show>
  );
}

/** Het weergavemodel uit `formulier-model.ts` als formulier.
 *
 *  GROEPSKOP: alleen bij MEER DAN ÉÉN blok met rijen — bij één groep ís het
 *  kv-blok de groep, en een kopje erboven zou ruis zijn. Een ONGEGROEPEERDE rij
 *  wordt een alinea met haar label ervoor; zo staat de eerlijkheidsnoot
 *  (rdfs:comment, sh:order 90) onder de velden. */
export function Formulier(props: {
  m: FormVorm;
  /** De titelregel. `false` waar de kop er al staat. */
  kop?: boolean;
  /** De knoop waarop deze rijen schrijven. Zonder term blijft het formulier
   *  kijkstand — er is dan geen adres om naartoe te bewerken. */
  term?: string | null;
}): JSX.Element {
  const kop = () => props.kop !== false;
  const groepen = () => props.m.blocks.filter((b) => b.kind === 'group');
  const rijen = (rows: FormRij[]): KvRij[] => rows.map((r) => ({
    label: r.label,
    desc: r.description,
    waarde: <Rijwaarde rij={r} term={props.term} />,
  }));
  return (
    <div class="artifact-form">
      <Show when={kop()}>
        <div class="artifact-title">
          <span>{props.m.title}</span>
          {/* dash:KeyInfoRole: wat naast de titel hoort. De meegeleverde
              artefact-shape gebruikt hem niet; een eigen shape mag.

              MET EEN LETTERLIJKE SPATIE ERVOOR (eigenaarsmelding 14 sep 2026,
              de tweede helft van de dubbele-titel-melding: "Begrippenkader
              detentie-einde-berichtenBK-DETENTIE-001"). De titelregel zet haar
              tussenruimte met `gap`, en een gap komt niet mee in het klembord —
              exact dezelfde fout en dezelfde oplossing als in de vouwkop
              hierboven en in `voorwaarde-inhoud.tsx`. */}
          <For each={props.m.keyInfo}>{(it) => (
            <>
              <span class="c-ruimte"> </span>
              <span class="chip type">{it.text}</span>
            </>
          )}</For>
        </div>
      </Show>
      <Show when={props.m.description}>
        {(d) => <p class="muted"><LangeTekst tekst={d()} /></p>}
      </Show>
      <For each={props.m.blocks}>{(b) => (
        <Show
          when={b.kind === 'group' ? (b as { rows: FormRij[] }) : null}
          fallback={(
            <Show
              when={ongegroepeerdeVerwijzing(b as FormRij)}
              fallback={(
                <p class="artifact-note muted">
                  <span class="artifact-note-label">{b.label + ': '}</span>
                  {/* MEERREGELIG: de alinea-vorm is precies de plek waar vrije
                      tekst landt (de eerlijkheidsnoot van een artefact is drie
                      zinnen), en die hoort niet in een eenregelig veld waar Enter
                      meteen opslaat. */}
                  <Rijwaarde rij={b as FormRij} term={props.term} meerregelig />
                </p>
              )}
            >
              {/* EEN ONGEGROEPEERDE RIJ DIE NAAR EEN GEDEKTE KNOOP WIJST is geen
                  vrije tekst en dus geen alinea: er hoort een uitklap in, en een
                  `<details>` binnen een `<p>` sluit die alinea in de browser
                  voortijdig af. Zelfde woorden, zelfde opmaak, ander element —
                  en alleen voor deze rijen, zodat de eerlijkheidsnoot van het
                  artefactformulier letterlijk blijft wat zij was. */}
              <div class="artifact-note muted">
                <span class="artifact-note-label">{b.label + ': '}</span>
                <Rijwaarde rij={b as FormRij} term={props.term} />
              </div>
            </Show>
          )}
        >
          {(g) => (
            <>
              <Show when={groepen().length > 1 && b.label}>
                <div class="form-group-label">{b.label}</div>
              </Show>
              <Kv rijen={rijen(g().rows)} />
            </>
          )}
        </Show>
      )}</For>
    </div>
  );
}
