// Dun laagje om localStorage: viewervoorkeuren (zijnav open, kaart-standen).
// Alles in try/catch — tests en privémodus hebben geen (werkende) opslag.
const PREFIX = 'odrlvis.';

export function prefGet(key, fallback) {
  try {
    const raw = globalThis.localStorage?.getItem(PREFIX + key);
    if (raw === null || raw === undefined) return fallback;
    return JSON.parse(raw);
  } catch { return fallback; }
}

export function prefSet(key, value) {
  try { globalThis.localStorage?.setItem(PREFIX + key, JSON.stringify(value)); }
  catch { /* opslag onbeschikbaar: voorkeur gaat verloren, verder geen effect */ }
}
